// Browser-only sample: the preflop model for 6 players at 40 BB, one per ante structure,
// cut to the open spots and the most frequent answers. Every grid request gets this sample;
// a stack off the grid plays a short made-up live solve with progress and cancel.
import type { PreflopAnte, PreflopGrid, PreflopNode, PreflopProgress, PreflopSpots } from "./preflop-types";

const STACKS = [15, 20, 25, 30, 40, 50, 75, 100];

export function demoGrid(): PreflopGrid {
  return {
    players: [6, 8, 9],
    stacks: STACKS,
    antes: [
      { ante: "none", ante_bb: 0, bb_ante_bb: 0 },
      { ante: "classic", ante_bb: 0.125, bb_ante_bb: 0 },
      { ante: "big_blind", ante_bb: 0, bb_ante_bb: 1 },
    ],
    live_max_players: 9,
    live_min_stack_bb: 10,
    live_max_stack_bb: 100,
    target_exploitability_bb: 0.001,
  };
}

const listeners = new Set<(p: PreflopProgress) => void>();
let cancelled = false;

export function onProgress(handler: (p: PreflopProgress) => void): () => void {
  listeners.add(handler);
  return () => {
    listeners.delete(handler);
  };
}

export function demoCancel() {
  cancelled = true;
}

export async function demoSpots(ante: PreflopAnte, players: number, stackBb: number): Promise<PreflopSpots> {
  const sample = DATA[ante].spots;
  if (STACKS.includes(stackBb)) return sample;
  cancelled = false;
  let expl = 0.4;
  for (let it = 10; expl > 0.001; it += 10) {
    await new Promise((r) => setTimeout(r, 150));
    if (cancelled) throw new Error("Die Berechnung wurde abgebrochen.");
    expl *= 0.9;
    const p = { ante, players, stack_bb: stackBb, iterations: it, max_iterations: 4000, exploitability: Math.max(expl, 0.00099), target_exploitability: 0.001 };
    listeners.forEach((h) => h(p));
  }
  return { ...sample, stack_bb: stackBb, precomputed: false };
}

export function demoNode(ante: PreflopAnte, _players: number, _stackBb: number, node: number): PreflopNode {
  const hit = DATA[ante].nodes[node];
  if (!hit) throw new Error("Diesen Spot gibt es in der Vorschau nicht.");
  return hit;
}

